INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "宫室焚毁，唐昭宗寓尚书省", "start_year": 895, "end_year": 895, "time_original": "895年八月还京以后；确日未载", "dynasty": "唐", "description": "宫室焚毁，尚未修葺完成，唐昭宗寄居尚书省。百官往往缺袍笏、仆从和马。", "phases": [], "location_name": "尚书省", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2e5e1c8d-87ec-5b8d-bdd5-3a1887c7234e"}, {"title": "李克用授行营都统", "start_year": 895, "end_year": 895, "time_original": "895年八月还京后条；确日未载", "dynasty": "唐", "description": "朝廷以李克用为行营都统。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "985b6e71-d625-521a-b683-53de1e8089c9"}, {"title": "宰相孔纬去世", "start_year": 895, "end_year": 895, "time_original": "895年九月癸亥", "dynasty": "唐", "description": "司空兼门下侍郎、同平章事孔纬去世。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "1f96e6b2-7cf1-5797-8581-2440a685b62e"}, {"title": "朱温亲征朱瑄，梁山败瑄", "start_year": 895, "end_year": 895, "time_original": "895年九月辛未", "dynasty": "唐", "description": "朱温亲率军攻朱瑄，两军在梁山交战，朱瑄败走回郓。", "phases": [], "location_name": "梁山、郓", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e960f624-1084-5b04-bf13-ce37a4588a05"}, {"title": "李克用急攻梨园，王行瑜求救李茂贞", "start_year": 895, "end_year": 895, "time_original": "895年九月条；确日未载", "dynasty": "唐", "description": "李克用加紧进攻梨园，王行瑜向李茂贞求救。", "phases": [], "location_name": "梨园", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "59201416-d318-50a6-a876-20a359a9d316"}, {"title": "李茂贞遣万人屯龙泉，自将三万屯咸阳旁", "start_year": 895, "end_year": 895, "time_original": "895年九月王行瑜求救以后；确日未载", "dynasty": "唐", "description": "李茂贞派兵一万人驻龙泉镇，自己率三万人驻咸阳附近。", "phases": [], "location_name": "龙泉镇、咸阳之旁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "72d3ff44-ad41-5db3-aaf4-18a4b52a5428"}, {"title": "李克用请求令茂贞归镇削爵，欲分兵讨之", "start_year": 895, "end_year": 895, "time_original": "895年九月茂贞援行瑜条；确日未载", "dynasty": "唐", "description": "李克用请求朝廷诏令李茂贞归镇，并削其官爵，打算分兵讨伐。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "e12f5cd0-7478-517e-a235-82385d48e106"}, {"title": "皇帝拒再削讨茂贞，只命归镇和解", "start_year": 895, "end_year": 895, "time_original": "895年九月李克用请讨以后；确日未载", "dynasty": "唐", "description": "唐昭宗以李茂贞已自诛李继鹏、此前已赦为由，不许再次削爵讨伐，只诏其归镇，并令李克用与之和解。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d8175545-298a-585b-8351-08ffd2a3a3af"}, {"title": "李罕之检校侍中，授邠宁四面副都统", "start_year": 895, "end_year": 895, "time_original": "895年九月条；确日未载", "dynasty": "唐", "description": "朝廷以昭义节度使李罕之检校侍中，充邠宁四面行营副都统。", "phases": [], "location_name": "邠宁、朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ea44f457-a7cb-5360-a3ca-2abb885948df"}, {"title": "史俨云阳败邠宁兵，擒王令诲献之", "start_year": 895, "end_year": 895, "time_original": "895年九月条；确日未载", "dynasty": "唐", "description": "史俨在云阳击败邠宁军，擒云阳镇使王令诲等人献上。", "phases": [], "location_name": "云阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "afbff379-b766-50b3-8784-824be74b6e13"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

